"""Focused six-arm research comparison, independent from the main price timeline."""
CSS=r"""
.d8-header{display:flex;justify-content:space-between;gap:25px;align-items:end;margin:26px 0}.d8-header h2{font-size:34px;letter-spacing:-1px;margin:8px 0}.d8-note{font:25px/1.2 Caveat,cursive;color:#426454;max-width:230px;transform:rotate(-2deg)}.d8-controls{display:flex;gap:16px;flex-wrap:wrap;padding:16px 0;border-block:1px solid #d8d9cd}.d8-controls label{display:grid;gap:6px;font-size:11px;color:#43595b}.d8-controls select{max-width:100%;min-width:120px;padding:8px;background:#fffdf7;border:1px solid #c2cabc;border-radius:5px;color:#1e3036}.d8-grid{display:grid;grid-template-columns:1.35fr 1fr;gap:26px;margin-top:28px}.d8-sheet{background:#fffdf8;border:1px solid #d8d9cd;border-radius:12px;padding:24px;min-width:0}.d8-sheet h3{font-size:17px;font-weight:500;margin:0 0 8px}.d8-small{font-size:12px;line-height:1.7;color:#465e60}.d8-sheet svg{width:100%;height:auto;display:block}.d8-sheet svg text{font-family:-apple-system,BlinkMacSystemFont,sans-serif;fill:#334e52;font-size:12px}.d8-table{width:100%;border-collapse:collapse;font-size:12px;font-variant-numeric:tabular-nums}.d8-table th,.d8-table td{text-align:left;padding:9px 4px;border-bottom:1px solid #e9e7db}.d8-table th{font-size:10px;color:#506365;font-weight:500}.d8-action{padding:7px 12px;border:1px solid #acbcae;border-radius:5px;background:#fffdf6;color:#203f3e;cursor:pointer}.d8-pin{padding:15px;background:#f5f3e8;border-left:2px solid #3554bc;margin-top:10px;overflow-wrap:anywhere}.d8-axes{font-variant-numeric:tabular-nums}.d8-banner{border-left:2px solid #335dcc;padding:5px 18px;margin:20px 0}.d8-sheet details{margin-top:18px}.d8-sheet summary{cursor:pointer;font-size:12px}.d8-full{margin-top:26px}.d8-scroll{max-width:100%;overflow:auto}.d8-sheet [role=button]:focus-visible{outline:2px solid #244cbb}.d8-empty{padding:35px;border:1px dashed #b5c3b5;border-radius:12px;margin:24px 0}
@media(max-width:760px){.d8-grid{grid-template-columns:1fr;gap:16px}.d8-sheet{padding:16px}.d8-header{display:block}.d8-header h2{font-size:28px}.d8-note{margin-top:12px;max-width:none}.d8-controls{gap:12px}.d8-controls label{flex:1;min-width:120px}.d8-controls label:last-child{flex-basis:100%}.d8-table{font-size:11px}.d8-small{font-size:11px}}
"""
JS=r"""
let D8=null,D8Error=null,D8Extra={},D8S={h:7,series:'all',outcome:'all',selected:'A',pins:[]};
const d8Names={A:'Official drift',B:'Drift + calibration',C:'Pooled changes',D:'Pooled + calibration',E:'Offer replay',F:'Replay + calibration'};
const d8Colors={A:'#607878',B:'#92a6a0',C:'#3154bd',D:'#8095d6',E:'#99752c',F:'#c9af6e'};
function d8Rows(){return D8?D8.cells.filter(r=>r.horizon===D8S.h&&(D8S.series==='all'||r.series_id===D8S.series)&&(D8S.outcome==='all'||r.changed===(D8S.outcome==='changed'))):[]}
function d8Mean(xs){return xs.length?xs.reduce((a,b)=>a+b,0)/xs.length:null}
function d8Stats(m,rows=d8Rows()){const rs=rows.filter(r=>r.method===m);return {m,n:rs.length,origins:new Set(rs.map(r=>r.origin)).size,loss:d8Mean(rs.map(r=>r.loss)),coverage:d8Mean(rs.map(r=>+(r.quantiles[0]<=r.truth&&r.truth<=r.quantiles[2]))),width:d8Mean(rs.map(r=>r.quantiles[2]-r.quantiles[0])),fallbacks:rs.filter(r=>r.diagnostic.fallback).length}}
function d8Num(v,n=5){return v===null||!Number.isFinite(v)?'—':v.toLocaleString(undefined,{maximumFractionDigits:n,minimumFractionDigits:Math.min(n,2)})}
function d8Label(s){return s.replace('afhubbard.','').replace('.median','').replaceAll('_',' ').replaceAll('.',' · ')}
function d8Bars(stats){
 const max=Math.max(...stats.map(s=>s.loss||0),.000001)*1.12,W=720,H=330,left=164,right=80,top=22,row=45;
 return '<svg viewBox="0 0 '+W+' '+H+'" role="img" aria-label="Matched pinball loss by registered arm. Lower is better.">'+[0,.5,1].map(t=>'<line x1="'+(left+t*(W-left-right))+'" x2="'+(left+t*(W-left-right))+'" y1="12" y2="291" stroke="#e1e5dd"/><text x="'+(left+t*(W-left-right))+'" y="318" text-anchor="middle">'+d8Num(t*max,4)+'</text>').join('')+stats.map((s,i)=>'<g data-d8-arm="'+s.m+'" tabindex="0" role="button" aria-label="'+esc(d8Names[s.m]+', loss '+d8Num(s.loss,6)+', '+s.n+' cells')+'"><text x="'+(left-13)+'" y="'+(top+i*row+18)+'" text-anchor="end">'+esc(d8Names[s.m])+'</text><rect x="'+left+'" y="'+(top+i*row)+'" width="'+((s.loss||0)/max*(W-left-right))+'" height="28" rx="2" fill="'+d8Colors[s.m]+'" opacity="'+(D8S.selected===s.m?1:.78)+'"/><text x="'+(left+(s.loss||0)/max*(W-left-right)+9)+'" y="'+(top+i*row+18)+'">'+d8Num(s.loss,5)+'</text></g>').join('')+'</svg>'
}
function d8Coverage(stats){
 const W=460,H=330,L=57,R=22,T=25,B=50,maxW=Math.max(...stats.map(s=>s.width||0),.00001)*1.16,x=v=>L+v/maxW*(W-L-R),y=v=>T+(1-v)*(H-T-B);
 return '<svg viewBox="0 0 '+W+' '+H+'" role="img" aria-label="Interval coverage versus mean width. The dashed line marks nominal eighty percent coverage.">'+[0,.4,.8,1].map(t=>'<line x1="'+L+'" x2="'+(W-R)+'" y1="'+y(t)+'" y2="'+y(t)+'" stroke="'+(t===.8?'#738da1':'#e2e6dc')+'" '+(t===.8?'stroke-dasharray="4 4"':'')+'/><text x="'+(L-9)+'" y="'+(y(t)+4)+'" text-anchor="end">'+Math.round(t*100)+'%</text>').join('')+stats.filter(s=>s.n).map((s,i)=>'<g data-d8-arm="'+s.m+'" tabindex="0" role="button" aria-label="'+esc(d8Names[s.m]+', coverage '+Math.round(s.coverage*100)+' percent, width '+d8Num(s.width))+'"><circle cx="'+x(s.width)+'" cy="'+y(s.coverage)+'" r="'+(D8S.selected===s.m?8:6)+'" fill="'+d8Colors[s.m]+'" stroke="#fffdf8" stroke-width="2"/><text x="'+(x(s.width)+10)+'" y="'+(y(s.coverage)+(i%2?16:-10))+'">'+s.m+'</text></g>').join('')+'<text x="'+((W+L)/2)+'" y="324" text-anchor="middle">Mean interval width · USD / GPU-hour</text>'+[0,.5,1].map(t=>'<text x="'+x(t*maxW)+'" y="300" text-anchor="middle">'+d8Num(t*maxW,3)+'</text>').join('')+'</svg>'
}
function dynamicsPage(){
 if(!D8)return '<div class="d8-empty"><h2>'+(D8Error?'The new study could not load.':'Opening the registered six-arm study…')+'</h2><p>No substitute scores are shown.</p><button class="d8-action" id="d8-retry">Retry study</button></div>';
 const stats=Object.keys(d8Names).map(m=>d8Stats(m)),sel=d8Stats(D8S.selected),scope=stats[0],a=stats[0],c=stats[2],chosen=stats.find(s=>s.m===D8S.selected);
 const pairs=[['C','A','Pooling / state model'],['E','A','Replay model'],['B','A','Calibrate drift'],['D','C','Calibrate pooled'],['F','E','Calibrate replay']];
 const extras=D8Extra;
 return '<div class="d8-header"><div><div class="eyebrow">PRICE DYNAMICS · V8 · RETROSPECTIVE</div><h2>What actually changed the forecast?</h2><p class="d8-small">Eight declared H100/A100 collector medians. One matched comparison, with failures kept in the denominator.</p></div><div class="d8-note">Better intervals can matter as much as a cleverer model.</div></div><div class="d8-controls"><label>Horizon<select id="d8-h">'+[7,3,1].map(h=>'<option value="'+h+'" '+(h===D8S.h?'selected':'')+'>'+h+' days'+(h===7?' · primary':' · secondary')+'</option>').join('')+'</select></label><label>Observed outcome<select id="d8-outcome">'+[['all','All eligible prices'],['changed','Price changed'],['unchanged','Price unchanged']].map(([k,t])=>'<option value="'+k+'" '+(D8S.outcome===k?'selected':'')+'>'+t+'</option>').join('')+'</select></label><label>Collector / configuration<select id="d8-series"><option value="all">All declared series</option>'+D8.cohort.series_ids.map(s=>'<option value="'+esc(s)+'" '+(D8S.series===s?'selected':'')+'>'+esc(d8Label(s))+'</option>').join('')+'</select></label></div><div class="d8-banner"><b>'+scope.n+' matched cells · '+scope.origins+' dependent origins</b><p class="d8-small">Lower pinball loss is better. '+D8.cohort.missing_target_pairs+' missing target pairs excluded before scoring. These are opened historical dates; prospective improvement is not yet established.</p></div><div class="d8-grid"><section class="d8-sheet"><h3>Forecast loss, on the same cells</h3><p class="d8-small">Solid tones: base method. Lighter tones: the same method with matured-error calibration.</p>'+d8Bars(stats)+'<div class="d8-small" id="d8-selected"><b>'+esc(d8Names[D8S.selected])+'</b> · '+sel.n+' cells · '+sel.fallbacks+' registered fallbacks.<br>Coverage '+(sel.coverage===null?'—':Math.round(sel.coverage*100)+'%')+' · width '+d8Num(sel.width)+' USD/GPU-hour.</div><button class="d8-action" id="d8-pin">Pin this comparison</button></section><section class="d8-sheet"><h3>Coverage and the price of wider intervals</h3><p class="d8-small">The dashed line is the nominal 80% level. A small dependent cohort does not establish calibration.</p>'+d8Coverage(stats)+'</section></div><section class="d8-sheet d8-full"><h3>Modeling gain or calibration gain?</h3><p class="d8-small">Candidate minus reference loss: negative favors the candidate. Filtered views are descriptive; registered block-bootstrap ranges appear only for the full cohort.</p><table class="d8-table"><thead><tr><th>Question</th><th>Paired difference</th><th>95% descriptive range</th></tr></thead><tbody>'+pairs.map(([cand,ref,title])=>{const x=d8Stats(cand),y=d8Stats(ref),r=D8.pairs.find(r=>r.candidate===cand&&r.reference===ref&&r.horizon===D8S.h);return '<tr><td>'+title+' ('+cand+'−'+ref+')</td><td>'+d8Num(x.loss===null?null:x.loss-y.loss,6)+'</td><td>'+(D8S.series==='all'&&D8S.outcome==='all'&&r?r.block_bootstrap_95.map(v=>d8Num(v,6)).join(' to '):'Full cohort only')+'</td></tr>'}).join('')+'</tbody></table><details id="d8-changed"><summary>Changed versus unchanged price outcomes</summary><p class="d8-small">Outcome changes are evaluation diagnostics, never input features.</p><table class="d8-table"><thead><tr><th>Arm</th><th>Changed n / loss</th><th>Unchanged n / loss</th></tr></thead><tbody>'+stats.map(s=>{const all=D8.cells.filter(r=>r.horizon===D8S.h&&(D8S.series==='all'||r.series_id===D8S.series)),x=d8Stats(s.m,all.filter(r=>r.changed)),y=d8Stats(s.m,all.filter(r=>!r.changed));return '<tr><td>'+s.m+'</td><td>'+x.n+' / '+d8Num(x.loss)+'</td><td>'+y.n+' / '+d8Num(y.loss)+'</td></tr>'}).join('')+'</tbody></table></details></section><section class="d8-sheet d8-full"><h3>Can listing replay reproduce the measured target?</h3><p class="d8-small">Official targets include every shipped snapshot in a UTC day. Last quotes per identity can describe a different population. Collection completeness is not inferred from an offer disappearing.</p>'+((D8Extra.rounding?.numpy_round_matches===D8Extra.rounding?.days)?'<p class="d8-small">Supplementary audit: NumPy source rounding reconstructs all '+D8Extra.rounding.days+' A100 40GB spot medians. The initial scalar-rounding discrepancies below are retained; forecasts and gates are unchanged.</p>':'')+'<div class="d8-scroll"><table class="d8-table"><thead><tr><th>Series</th><th>Raw target match</th><th>Last-quote match</th><th>Max difference</th></tr></thead><tbody>'+D8.target_audit.map(r=>'<tr><td>'+esc(d8Label(r.series_id))+'</td><td>'+r.raw_target_exact_days+'/'+r.days+'</td><td>'+r.last_quote_basket_exact_days+'/'+r.days+'</td><td>'+d8Num(r.max_basket_error,4)+'</td></tr>').join('')+'</tbody></table></div><details id="d8-provenance"><summary>Inputs, official scorer and reproducibility</summary><p class="d8-small">All '+D8.official_scorer_verification.reduce((a,r)=>a+r.verified_cells,0)+' arm/reference scores verified against the unmodified official scorer. Zero optimizer updates. Provider-reported cost: unknown.<br>Source revision '+esc(D8.source_sha)+'<br>Configuration '+esc(D8.protocol_sha256)+'<br>Input snapshot '+esc(D8.input_sha256)+'</p><p><a href="/api/price-dynamics-v8">Exact result artifact</a> · <a href="https://github.com/howdymary/mochi-demo/blob/compute-observatory/docs/price-dynamics-v8.md">Methods, attribution & reproduction</a></p></details></section><section class="d8-sheet d8-full"><h3>Next decisions, with a paper trail</h3><p class="d8-small">Retrospective methods: '+(D8? 'completed with matched controls':'pending')+'. '+(extras.future?'Future panel: '+esc(extras.future.status)+'. ':'Future panel awaits capture verification. ')+'No method is promoted from reopened dates.</p><p class="d8-small">'+(extras.news?.discovery?'Evidence capture: '+extras.news.discovery.returned_items+' retrieved items, cap '+extras.news.discovery.requested_cap+'. '+esc(extras.news.discovery.collection_coverage)+'.':'New evidence capture status is separate from this price-only experiment.')+'</p><p class="d8-small">'+(extras.memory?'Shared-memory cross-role uses verified: '+extras.memory.reads.filter(r=>r.verified_cross_role_use).length+'. '+esc(extras.memory.final_decision||''):'Memory receipt pending; no recall claim is inferred.')+'</p><p><a href="/api/price-dynamics-v8/extra/future">Future panel</a> · <a href="/api/price-dynamics-v8/extra/news">Evidence measurement</a> · <a href="/api/price-dynamics-v8/extra/memory">Memory receipts</a></p></section><div id="d8-pins">'+D8S.pins.map(p=>'<article class="d8-pin"><b>'+esc(p.label)+'</b><p class="d8-small">Pinned '+esc(p.created_at)+' · '+p.horizon+' days · '+p.n+' cells · loss '+d8Num(p.loss,6)+'<br>'+esc(p.series)+' · '+esc(p.outcome)+'<br>Artifact '+esc(p.artifact_sha256)+'</p></article>').join('')+'</div>';
}
function bindDynamics(){
 if($('#d8-retry'))$('#d8-retry').onclick=loadDynamics;
 for(const [id,key] of [['d8-h','h'],['d8-series','series'],['d8-outcome','outcome']])if($('#'+id))$('#'+id).onchange=e=>{D8S[key]=key==='h'?+e.target.value:e.target.value;render()};
 document.querySelectorAll('[data-d8-arm]').forEach(el=>{const select=()=>{D8S.selected=el.dataset.d8Arm;render()};el.onclick=select;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select()}}});
 if($('#d8-pin'))$('#d8-pin').onclick=()=>{const s=d8Stats(D8S.selected);D8S.pins.push(JSON.parse(JSON.stringify({label:d8Names[D8S.selected],created_at:new Date().toISOString(),horizon:D8S.h,series:D8S.series,outcome:D8S.outcome,n:s.n,loss:s.loss,artifact_sha256:D8.stored_artifact_sha256||D8.protocol_sha256,configuration_sha256:D8.protocol_sha256})));render()};
}
const d8PrevRender=render;render=function(){const focused=document.activeElement?.getAttribute('data-d8-arm'),details={};document.querySelectorAll('[id^="d8-"] details,details[id^="d8-"]').forEach(e=>details[e.id]=e.open);d8PrevRender();if(view==='research'&&researchTab==='dynamics'){bindDynamics();for(const [id,open] of Object.entries(details))if($('#'+id))$('#'+id).open=open;if(focused)document.querySelector('[data-d8-arm="'+focused+'"]')?.focus({preventScroll:true})}};
async function loadDynamics(){D8Error=null;try{const v=await fetchJson('/api/price-dynamics-v8');if(v.schema_version!==8||v.study_id!=='price-dynamics-v8')throw Error('Study identity');D8=v}catch(e){D8Error=e}if(P&&view==='research'&&researchTab==='dynamics')render()}
for(const name of ['future','news','memory','rounding'])fetchJson('/api/price-dynamics-v8/extra/'+name).then(v=>{D8Extra[name]=v;if(P&&view==='research'&&researchTab==='dynamics')render()}).catch(()=>{});
loadDynamics();
"""
def enhance(html):
    for old,new in [("['visual','Research atlas']","['dynamics','Price dynamics'],['visual','Research atlas']"),
                    ("visual:researchAtlas,results,","visual:researchAtlas,dynamics:dynamicsPage,results,")]:
        if html.count(old)!=1:raise ValueError("Dynamics insertion marker changed: "+old)
        html=html.replace(old,new)
    return html.replace("</style>",CSS+"</style>").replace("</script>",JS+"</script>")
